#!/bin/bash
# Phase 2 TG 2.1: Pocket Proposal Execution Script
# Generated by egfr_pipeline.phase2.pocket_proposal
#
# Run this script on the production server where fpocket and/or P2Rank
# are installed. Both tools are optional — the parser handles missing output.
#
# Usage:
#   bash pocket_proposal_run.sh
#   bash pocket_proposal_run.sh fpocket    # fpocket only
#   bash pocket_proposal_run.sh p2rank     # P2Rank only

set -euo pipefail

OUTPUT_BASE="/home/user/codex_ligand/output/phase2_pockets"
TOOL="${1:-all}"

echo '=== Phase 2 TG 2.1: Pocket Proposal ==='
echo

# --- fpocket ---
if [[ "$TOOL" == "all" || "$TOOL" == "fpocket" ]]; then
  echo "--- Running fpocket ---"
  if ! command -v fpocket &>/dev/null; then
    echo "WARNING: fpocket not found in PATH. Skipping."
  else
    echo "  State: 3GT8_raw"
    mkdir -p "/home/user/codex_ligand/output/phase2_pockets/3GT8_raw"
    cp "/home/user/codex_ligand/input/PPI/phase1/receptor_3GT8_raw.pdb" "/home/user/codex_ligand/output/phase2_pockets/3GT8_raw/receptor_3GT8_raw.pdb"
    cd "/home/user/codex_ligand/output/phase2_pockets/3GT8_raw"
    fpocket -f "receptor_3GT8_raw.pdb"
    cd "$OUTPUT_BASE"
    echo "    Done: 3GT8_raw"
    echo "  State: 3GT8_cl38_48"
    mkdir -p "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl38_48"
    cp "/home/user/codex_ligand/input/PPI/phase1/receptor_3GT8_cl38_48.pdb" "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl38_48/receptor_3GT8_cl38_48.pdb"
    cd "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl38_48"
    fpocket -f "receptor_3GT8_cl38_48.pdb"
    cd "$OUTPUT_BASE"
    echo "    Done: 3GT8_cl38_48"
    echo "  State: 3GT8_cl85_100"
    mkdir -p "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl85_100"
    cp "/home/user/codex_ligand/input/PPI/phase1/receptor_3GT8_cl85_100.pdb" "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl85_100/receptor_3GT8_cl85_100.pdb"
    cd "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl85_100"
    fpocket -f "receptor_3GT8_cl85_100.pdb"
    cd "$OUTPUT_BASE"
    echo "    Done: 3GT8_cl85_100"
  fi
  echo
fi

# --- P2Rank ---
if [[ "$TOOL" == "all" || "$TOOL" == "p2rank" ]]; then
  echo "--- Running P2Rank ---"
  if ! command -v prank &>/dev/null; then
    echo "WARNING: prank (P2Rank) not found in PATH. Skipping."
  else
    echo "  State: 3GT8_raw"
    mkdir -p "/home/user/codex_ligand/output/phase2_pockets/3GT8_raw"
    prank predict -f "/home/user/codex_ligand/input/PPI/phase1/receptor_3GT8_raw.pdb" -o "/home/user/codex_ligand/output/phase2_pockets/3GT8_raw/p2rank_output"
    echo "    Done: 3GT8_raw"
    echo "  State: 3GT8_cl38_48"
    mkdir -p "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl38_48"
    prank predict -f "/home/user/codex_ligand/input/PPI/phase1/receptor_3GT8_cl38_48.pdb" -o "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl38_48/p2rank_output"
    echo "    Done: 3GT8_cl38_48"
    echo "  State: 3GT8_cl85_100"
    mkdir -p "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl85_100"
    prank predict -f "/home/user/codex_ligand/input/PPI/phase1/receptor_3GT8_cl85_100.pdb" -o "/home/user/codex_ligand/output/phase2_pockets/3GT8_cl85_100/p2rank_output"
    echo "    Done: 3GT8_cl85_100"
  fi
  echo
fi

echo "=== Pocket proposal complete ==="
echo "Run parser: python -m egfr_pipeline.phase2.pocket_proposal --parse"